51	#[derive(Debug, Deserialize)]
52	struct ModelLenConfig {
53	    max_position_embeddings: Option<u32>,
54	    text_config: Option<Box<ModelLenConfig>>,
55	}
56	
57	impl ModelLenConfig {
58	    fn max_model_len(&self) -> Option<u32> {
59	        self.max_position_embeddings
60	            .or_else(|| self.text_config.as_ref()?.max_model_len())
61	    }
62	}
