64	/// Serve while the engine is still loading: the HTTP frontend (tokenizer,
65	/// chat templates) starts immediately and the engine bridge attaches once
66	/// `engine` resolves. HTTP binds only after the bridge registers, so a
67	/// reachable port still means the engine is ready.
68	///
69	/// Pass `max_model_len: None` to read `max_position_embeddings` from
70	/// `model_path/config.json`; pass `Some(n)` when the path has no config
71	/// (e.g. a HuggingFace model id for the sim frontend).
72	/// `tool_call_parser` selects the output tool-call parser (see the
73	/// `--tool-call-parser` CLI flag for the `Auto` matching caveat).
74	pub async fn serve(
75	    engine: impl Future<Output = Result<LaunchedEngine>> + Send + 'static,
76	    model_path: &Path,
77	    served_model_name: Vec<String>,
78	    tool_call_parser: ParserSelection,
79	    port: u16,
80	    max_model_len: Option<u32>,
81	    shutdown: CancellationToken,
82	) -> Result<()> {
83	    serve_with_engine_count(
84	        engine,
85	        model_path,
86	        served_model_name,
87	        tool_call_parser,
88	        port,
89	        max_model_len,
90	        1,
91	        shutdown,
92	    )
93	    .await
94	}
95	
96	/// Serve one HTTP endpoint backed by `engine_count` frontend-visible engine
97	/// identities. Data-parallel model lines use one identity per scheduler
98	/// partition; ordinary model lines call [`serve`] and get the single-engine
99	/// case.
100	pub async fn serve_with_engine_count(
101	    engine: impl Future<Output = Result<LaunchedEngine>> + Send + 'static,
102	    model_path: &Path,
103	    served_model_name: Vec<String>,
104	    tool_call_parser: ParserSelection,
105	    port: u16,
106	    max_model_len: Option<u32>,
107	    engine_count: usize,
108	    shutdown: CancellationToken,
109	) -> Result<()> {
110	    serve_model_on_host(
111	        engine,
112	        model_path.to_string_lossy().into_owned(),
113	        served_model_name,
114	        tool_call_parser,
115	        "0.0.0.0".to_string(),
116	        port,
117	        resolve_max_model_len(model_path, max_model_len),
118	        engine_count,
119	        shutdown,
120	    )
121	    .await
122	}
