124	/// Serve as [`serve_with_engine_count`] does, behind the caller's routes:
125	/// `extend_router` takes the vLLM router and returns the one that listens.
126	/// An engine refuses what it does not serve here, with a 400 before the
127	/// request reaches it, as the prefill-only contract does.
128	#[allow(clippy::too_many_arguments)]
129	pub async fn serve_with_router_extension<F>(
130	    engine: impl Future<Output = Result<LaunchedEngine>> + Send + 'static,
131	    model_path: &Path,
132	    served_model_name: Vec<String>,
133	    tool_call_parser: ParserSelection,
134	    port: u16,
135	    max_model_len: Option<u32>,
136	    engine_count: usize,
137	    shutdown: CancellationToken,
138	    extend_router: F,
139	) -> Result<()>
140	where
141	    F: FnOnce(Router) -> Router,
142	{
143	    serve_model_on_host_with_router_extension(
144	        engine,
145	        model_path.to_string_lossy().into_owned(),
146	        served_model_name,
147	        tool_call_parser,
148	        "0.0.0.0".to_string(),
149	        port,
150	        resolve_max_model_len(model_path, max_model_len),
151	        engine_count,
152	        shutdown,
153	        extend_router,
154	    )
155	    .await
156	}
