21	/// A sampled position: the chosen token, then its top-k without repeating it.
22	/// The chat renderer takes the first `k` entries as the alternatives, so a
23	/// repeat would push out a real candidate.
24	pub(crate) fn to_wire_position_logprobs(
25	    token_id: u32,
26	    logprob: Option<TokenLogprob>,
27	) -> Option<PositionLogprobs> {
28	    Some(position_logprobs(token_id, logprob?, false))
29	}
30	
31	/// The scored token, then its top-k. A prompt position keeps a repeat of the
32	/// scored token (`keep_repeat`): the encoder needs every row of one payload
33	/// equally wide, and prompt positions render as per-token maps, where the
34	/// repeat collapses.
35	fn position_logprobs(token_id: u32, lp: TokenLogprob, keep_repeat: bool) -> PositionLogprobs {
36	    let mut entries = Vec::with_capacity(1 + lp.top_logprobs.len());
37	    entries.push(WireTokenLogprob {
38	        token_id,
39	        logprob: lp.logprob,
40	        rank: lp.rank,
41	    });
42	    for (index, (alt_id, alt_logprob)) in lp.top_logprobs.into_iter().enumerate() {
43	        if !keep_repeat && alt_id == token_id {
44	            continue;
45	        }
46	        entries.push(WireTokenLogprob {
47	            token_id: alt_id,
48	            logprob: alt_logprob,
49	            rank: (index + 1) as u32,
50	        });
51	    }
52	    PositionLogprobs { entries }
53	}
