203	pub(crate) fn requested_logprobs(params: &EngineCoreSamplingParams) -> Option<usize> {
204	    params.logprobs.map(|count| count as usize)
205	}
206	
207	pub(crate) fn requested_prompt_logprobs(params: &EngineCoreSamplingParams) -> Option<usize> {
208	    params.prompt_logprobs.map(|count| count as usize)
209	}
