55	/// The engine includes the unscored leading token; vLLM restores it itself.
56	/// Never drop a missing scored position: every following offset would shift.
57	pub(crate) fn to_wire_prompt_logprobs(prompt: PromptEcho) -> Result<Option<MaybeWireLogprobs>> {
58	    ensure!(
59	        !prompt.ids.is_empty(),
60	        "prompt logprobs contain an empty prompt"
61	    );
62	    ensure!(
63	        prompt.ids.len() == prompt.logprobs.len(),
64	        "prompt logprobs length mismatch: {} tokens, {} scores",
65	        prompt.ids.len(),
66	        prompt.logprobs.len()
67	    );
68	    ensure!(
69	        prompt.logprobs[0].is_none(),
70	        "the first prompt token must have no logprob"
71	    );
72	    if prompt.ids.len() == 1 {
73	        return Ok(None);
74	    }
75	    let positions = prompt
76	        .ids
77	        .into_iter()
78	        .zip(prompt.logprobs)
79	        .enumerate()
80	        .skip(1)
81	        .map(|(index, (id, logprob))| {
82	            logprob
83	                .map(|lp| position_logprobs(id, lp, true))
84	                .with_context(|| format!("missing prompt logprob at position {index}"))
85	        })
86	        .collect::<Result<Vec<_>>>()?;
87	    Ok(Some(MaybeWireLogprobs::Direct(Logprobs { positions })))
88	}
