90	pub(crate) fn convert_sampling(params: &EngineCoreSamplingParams) -> SamplingParams {
91	    // The vLLM frontend lowers a client `ignore_eos=true` to `_eos_token_id:
92	    // None`, but `_all_stop_token_ids` always carries the model EOS set (it
93	    // exists for min_tokens masking, not stop detection). This conversion feeds
94	    // the legacy SamplingParams contract, which has no field for explicit
95	    // request stop IDs; keep its historical lowering until each producer is
96	    // migrated to StopPolicy. Qwen3 receives the independent policy below.
97	    let ignore_eos = params.eos_token_id.is_none() && params.stop_token_ids.is_empty();
98	    if params.temperature <= 0.0 {
99	        return SamplingParams {
100	            temperature: 0.0,
101	            top_k: -1,
102	            top_p: 1.0,
103	            min_p: 0.0,
104	            seed: None,
105	            ignore_eos,
106	        };
107	    }
108	
109	    SamplingParams {
110	        temperature: params.temperature,
111	        top_k: if params.top_k == 0 {
112	            -1
113	        } else {
114	            i32::try_from(params.top_k).unwrap_or(i32::MAX)
115	        },
116	        top_p: params.top_p,
117	        min_p: params.min_p,
118	        seed: params.seed.map(|s| s as u64),
119	        ignore_eos,
120	    }
121	}
