123	pub(crate) fn convert_stop_policy(params: &EngineCoreSamplingParams) -> StopPolicy {
124	    StopPolicy::new(
125	        // vLLM lowers secondary model EOS IDs into stop_token_ids. Keep its
126	        // primary EOS separate so secondary stops retain their wire reason;
127	        // all_stop_token_ids is only for min_tokens masking.
128	        params
129	            .eos_token_id
130	            .map_or(EosPolicy::Ignore, EosPolicy::Token),
131	        params.stop_token_ids.clone(),
132	    )
133	}
