135	/// Reject request parameters the frontend cannot represent faithfully.
136	///
137	/// The stepped contract carries explicit request stop IDs independently in
138	/// [`StopPolicy`]; this helper only validates unrelated sampling/transfer
139	/// fields that would otherwise be silently ignored.
140	/// Returns the offending description; `None` means the request is servable.
141	///
142	/// The float comparisons are exact on purpose: they detect "the client sent
143	/// anything other than the wire default", not numeric closeness — a request
144	/// carrying 1.0000001 wants a penalty and must be rejected, not rounded away.
145	#[allow(clippy::float_cmp)]
146	pub(crate) fn unsupported_request_params(params: &EngineCoreSamplingParams) -> Option<String> {
147	    // Engine-core clients may bypass HTTP validation; reject before converting to usize.
148	    if params.logprobs.is_some_and(|count| count < 0)
149	        || params.prompt_logprobs.is_some_and(|count| count < 0)
150	    {
151	        return Some("negative logprob counts are not supported".into());
152	    }
153	    if params.min_tokens != 0 {
154	        return Some(format!(
155	            "min_tokens={} is not supported by current engine contracts",
156	            params.min_tokens
157	        ));
158	    }
159	    if !(0.0..1.0).contains(&params.min_p) || !params.min_p.is_finite() {
160	        return Some(format!("min_p {} outside [0, 1)", params.min_p));
161	    }
162	    if params.frequency_penalty != 0.0 {
163	        return Some(format!(
164	            "frequency_penalty {} is not supported yet",
165	            params.frequency_penalty
166	        ));
167	    }
168	    if params.presence_penalty != 0.0 {
169	        return Some(format!(
170	            "presence_penalty {} is not supported yet",
171	            params.presence_penalty
172	        ));
173	    }
174	    if params.repetition_penalty != 1.0 {
175	        return Some(format!(
176	            "repetition_penalty {} is not supported yet",
177	            params.repetition_penalty
178	        ));
179	    }
180	    // The server lowers the client's ec_transfer_params into extra_args, and
181	    // this engine has no encoder cache connector to hand it to.
182	    if let Some(ec) = params
183	        .extra_args
184	        .as_ref()
185	        .and_then(|args| args.get("ec_transfer_params"))
186	    {
187	        let requested = match ec {
188	            serde_json::Value::Null => false,
189	            serde_json::Value::Object(map) => !map.is_empty(),
190	            _ => true,
191	        };
192	        if requested {
193	            return Some(
194	                "ec_transfer_params is not supported yet: this engine has no encoder cache \
195	                 connector"
196	                    .to_string(),
197	            );
198	        }
199	    }
200	    None
201	}
