211	pub(crate) fn lora_adapter_from_sampling_params(
212	    params: &EngineCoreSamplingParams,
213	) -> Result<Option<String>> {
214	    let Some(extra_args) = params.extra_args.as_ref() else {
215	        return Ok(None);
216	    };
217	    let Some(value) = extra_args.get(LORA_ADAPTER_XARG) else {
218	        return Ok(None);
219	    };
220	    match value.as_str() {
221	        Some(name) if !name.is_empty() => Ok(Some(name.to_string())),
222	        Some(_) => bail!("{LORA_ADAPTER_XARG} must not be empty"),
223	        None => bail!("{LORA_ADAPTER_XARG} must be a string"),
224	    }
225	}
