        std::future::ready(Ok(engine)),
        &shared.model_path,
        served_model_name,
        vllm::ParserSelection::Auto,
        shared.port,
        None,
        plan.scheduler_partition_count,
        vllm::shutdown_token_from_ctrl_c(),
    )
    .await
}

